local HingeMaker = {}
local PRODUCTS = {
    iron_hinge = { name = "Železen šarnir", ironCost = 1, time = 1, cost = 5, loadCapacity = 20, description = "Preprost železen šarnir za vrata." },
    strap_hinge = { name = "Pasasti šarnir", ironCost = 2, time = 2, cost = 16, loadCapacity = 35, prestige = 1, description = "Dolg pasasti šarnir za težka vrata." },
    brass_hinge = { name = "Medeninast šarnir", brassCost = 2, time = 3, cost = 38, loadCapacity = 30, prestige = 3, description = "Medeninast šarnir za okrasne omare." },
    t_hinge = { name = "T-šarnir", ironCost = 2, brassCost = 1, time = 4, cost = 80, loadCapacity = 50, prestige = 5, description = "T-oblikovan šarnir za vrata in dvižne sisteme." },
    silver_hinge = { name = "Srebrn šarnir", silverCost = 2, time = 5, cost = 165, loadCapacity = 45, prestige = 9, happiness = 1, description = "Srebrn šarnir za zakladne omare." },
    royal_pivot_hinge = { name = "Kraljevski vrtljivi šarnir", goldCost = 2, silverCost = 2, steelCost = 1, time = 8, cost = 430, loadCapacity = 80, prestige = 25, happiness = 4, description = "Veliki kraljevski šarnir z zlatimi in srebrnimi ležaji za slovesne dvižne sisteme." },
}
local BUILDINGS = {
    workshop = { name = "Šarnirska delavnica", cost = { gold = 190, wood = 100 }, upkeep = 4, qualityBonus = 5 },
    forge = { name = "Šarnirska kovačija", cost = { gold = 650, wood = 200, stone = 150 }, upkeep = 16, qualityBonus = 15 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 26, qualityBonus = 22 },
    royal_hinge_atelier = { name = "Kraljevski atelje šarnirjev", cost = { gold = 3200, wood = 400, stone = 500, gold = 30 }, upkeep = 62, qualityBonus = 36, prestigeBonus = 18 },
}
HingeMaker.ironStock = 16; HingeMaker.steelStock = 10; HingeMaker.brassStock = 6; HingeMaker.silverStock = 4; HingeMaker.goldStock = 3
HingeMaker.productStock = {}; HingeMaker.buildings = {}; HingeMaker.maker = nil; HingeMaker.activeMaking = {}; HingeMaker.totalProducts = 0; HingeMaker.dayTimer = 0
function HingeMaker.init() HingeMaker.ironStock=16; HingeMaker.steelStock=10; HingeMaker.brassStock=6; HingeMaker.silverStock=4; HingeMaker.goldStock=3; HingeMaker.productStock={}; HingeMaker.buildings={}; HingeMaker.maker=nil; HingeMaker.activeMaking={}; HingeMaker.totalProducts=0; HingeMaker.dayTimer=0; print("[HingeMaker] Royal Hinge Maker System initialized (6 products, 4 buildings)") end
function HingeMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HingeMaker.maker={name=n or ("Šarnirjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šarnirjar najet: %s (spretnost: %d)",HingeMaker.maker.name,s),"success") end; return true end
function HingeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HingeMaker.build(id) local ok,e=HingeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HingeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HingeMaker.getQualityBonus() local b=0; for _,bd in ipairs(HingeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HingeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HingeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and HingeMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.brassCost and HingeMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and HingeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HingeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #HingeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not HingeMaker.maker then return false,"Potreben šarnirjar" end; return true end
function HingeMaker.make(pt,qty) qty=qty or 5; local ok,e=HingeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HingeMaker.ironStock=HingeMaker.ironStock-d.ironCost*qty end; if d.steelCost then HingeMaker.steelStock=HingeMaker.steelStock-d.steelCost*qty end; if d.brassCost then HingeMaker.brassStock=HingeMaker.brassStock-d.brassCost*qty end; if d.silverCost then HingeMaker.silverStock=HingeMaker.silverStock-d.silverCost*qty end; if d.goldCost then HingeMaker.goldStock=HingeMaker.goldStock-d.goldCost*qty end; local t=d.time; if HingeMaker.maker then t=math.max(1,t-math.floor(HingeMaker.maker.skill/15)) end; table.insert(HingeMaker.activeMaking,{id="hinge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,loadCapacity=d.loadCapacity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HingeMaker.completeMaking(m) local q=1.0+(HingeMaker.getQualityBonus()/100); if HingeMaker.maker then q=q+(HingeMaker.maker.skill/200) end; q=math.min(2.0,q); HingeMaker.productStock[m.productType]=(HingeMaker.productStock[m.productType] or 0)+m.quantity; HingeMaker.totalProducts=HingeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HingeMaker.maker then HingeMaker.maker.itemsMade=HingeMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then HingeMaker.maker.skill=math.min(100,HingeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šarnirji izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function HingeMaker.update(dt) if not _G.state then return end; HingeMaker.dayTimer=HingeMaker.dayTimer+dt; if HingeMaker.dayTimer>=30 then HingeMaker.dayTimer=0; for i=#HingeMaker.activeMaking,1,-1 do local m=HingeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HingeMaker.completeMaking(m); table.remove(HingeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HingeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HingeMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HingeMaker.getStats() return {ironStock=HingeMaker.ironStock,steelStock=HingeMaker.steelStock,brassStock=HingeMaker.brassStock,silverStock=HingeMaker.silverStock,goldStock=HingeMaker.goldStock,productStock=HingeMaker.productStock,numBuildings=#HingeMaker.buildings,hasMaker=HingeMaker.maker~=nil,makerName=HingeMaker.maker and HingeMaker.maker.name or "—",makerSkill=HingeMaker.maker and HingeMaker.maker.skill or 0,activeMaking=#HingeMaker.activeMaking,totalProducts=HingeMaker.totalProducts} end
return HingeMaker
